package local.campus.review.workbench;
import com.fasterxml.jackson.databind.*;
import local.campus.review.auth.*;
import local.campus.review.common.*;
import local.campus.review.reference.*;
import local.campus.review.content.*;
import org.springframework.stereotype.Service;
import java.nio.file.*;
import java.util.*;
@Service
public class ReferenceImportService {
    final DatasetService data;final ReferenceProcessor references;final LibraryGenerationService libraries;final DocumentCodec codec;
    public ReferenceImportService(DatasetService data,ReferenceProcessor references,LibraryGenerationService libraries,DocumentCodec codec){this.data=data;this.references=references;this.libraries=libraries;this.codec=codec;}
    public record Start(String datasetId,String versionId){}
    public JsonNode create(CurrentUser actor,Start input){var dataset=data.dataset(actor,input.datasetId());var version=data.version(input.datasetId(),input.versionId());if(!"NEWS".equals(dataset.get("kind"))||!"CLEAN".equals(version.get("stage"))||!"READY".equals(version.get("status")))throw new ApiException(400,"VALIDATION_ERROR","请选择已完成的新闻清洗版本");String id=UUID.randomUUID().toString();data.db.update("INSERT INTO reference_import(id,dataset_id,version_id,created_by,status,created_at) VALUES(?,?,?,?,?,UTC_TIMESTAMP(3))",id,input.datasetId(),input.versionId(),actor.userId(),actor.role()==CurrentUser.Role.ADMIN?"QUEUED":"PENDING_APPROVAL");return data.json.createObjectNode().put("id",id);}
    public JsonNode list(CurrentUser actor,int page){data.role(actor);if(page<1)throw new ApiException(400,"VALIDATION_ERROR","分页无效");var result=data.json.createObjectNode().put("total",data.db.queryForObject("SELECT COUNT(*) FROM reference_import",Long.class));result.set("items",data.json.valueToTree(data.db.queryForList("SELECT r.id,r.dataset_id AS datasetId,r.version_id AS versionId,d.name,r.status,r.processed,r.inserted,r.duplicates,r.rejected,CAST(r.generation_id AS CHAR) AS generationId,r.error_message AS error FROM reference_import r JOIN ml_dataset d ON d.id=r.dataset_id ORDER BY r.created_at DESC LIMIT 20 OFFSET ?",(page-1L)*20)));result.put("activeGenerationId",libraries.currentId());return result;}
    public JsonNode rows(CurrentUser actor,String id,int page){data.role(actor);DatasetService.identity(id);if(page<1)throw new ApiException(400,"VALIDATION_ERROR","分页无效");var result=data.json.createObjectNode().put("total",data.db.queryForObject("SELECT COUNT(*) FROM reference_import_row WHERE batch_id=?",Long.class,id));result.set("items",data.json.valueToTree(data.db.queryForList("SELECT row_no AS rowNo,source_id AS sourceId,status,CAST(reference_work_id AS CHAR) AS referenceId,message FROM reference_import_row WHERE batch_id=? ORDER BY row_no LIMIT 20 OFFSET ?",id,(page-1L)*20)));return result;}
    public JsonNode action(CurrentUser actor,String id,String action){data.role(actor);DatasetService.identity(id);if(action.equals("APPROVE")){AccessPolicy.requireAdmin(actor);data.db.update("UPDATE reference_import SET status='QUEUED',error_message=NULL WHERE id=? AND status='PENDING_APPROVAL'",id);}else if(action.equals("RETRY")){AccessPolicy.requireAdmin(actor);data.db.update("UPDATE reference_import SET status='QUEUED',error_message=NULL WHERE id=? AND status IN ('FAILED','INTERRUPTED','WAITING_INDEX')",id);}else throw new ApiException(400,"VALIDATION_ERROR","操作无效");return data.json.createObjectNode().put("saved",true);}
    void run(Map<String,Object> job)throws Exception{
        String id=job.get("id").toString(),dataset=job.get("dataset_id").toString();var version=data.version(dataset,job.get("version_id").toString());var input=data.input(version);if(!ReleaseService.sha(input).equals(version.get("sha256")))throw new IllegalStateException("清洗版本校验失败");
        var known=new HashMap<String,String>();for(var old:data.db.queryForList("SELECT w.id,JSON_UNQUOTE(JSON_EXTRACT(r.artifacts_json,'$.plainText')) AS text FROM reference_work w JOIN reference_revision r ON r.reference_work_id=w.id WHERE r.revision_no=(SELECT MAX(x.revision_no) FROM reference_revision x WHERE x.reference_work_id=w.id AND x.processing_status IN ('PREPARED','READY','PARTIAL','IMPORTING')) AND (w.enabled=true OR w.id IN (SELECT reference_work_id FROM reference_import_row WHERE batch_id=?))",id)){String text=Objects.toString(old.get("text"),"");known.put(textHash(text),old.get("id").toString());}
        var done=new HashSet<Integer>(data.db.queryForList("SELECT row_no FROM reference_import_row WHERE batch_id=?",Integer.class,id));
        try(var reader=Files.newBufferedReader(input)){String line;int number=0;while((line=reader.readLine())!=null){number++;if(done.contains(number))continue;JsonNode row=data.json.readTree(line);int rowNo=number;String text=row.path("text").asText(),hash=textHash(text),old=known.get(hash),source=row.path("id").asText(Integer.toString(number));
            if(old!=null){record(id,rowNo,source,"DUPLICATE",old,"相同正文已存在");continue;}
            try{String title=row.path("title").asText();if(title.isBlank())title="原稿 "+source;var content=data.json.createObjectNode().put("type","doc");var blocks=content.putArray("content");for(String part:text.split("\n",-1)){var p=blocks.addObject().put("type","paragraph");p.putObject("attrs").put("nodeId",UUID.randomUUID().toString());if(!part.isEmpty())p.putArray("content").addObject().put("type","text").put("text",part);}
                var extracted=codec.validateForSubmission(new DocumentModels.DocumentInput(title,"1",content,List.of()));String finalTitle=title;String work=data.transactions.execute(tx->{long w=SqlSupport.insert(data.db,"INSERT INTO reference_work(origin_type,enabled,created_by,created_at) VALUES('MANUAL',false,?,UTC_TIMESTAMP(3))",job.get("created_by"));var metadata=data.json.createObjectNode().put("sourceType","DATASET").put("datasetId",dataset).put("versionId",version.get("id").toString()).put("importBatchId",id).put("sourceId",source).put("description","清洗新闻批量导入");metadata.set("provenance",row);String url=row.path("url").asText();if(!url.isBlank()){codec.checkUrl(url,false);metadata.put("url",url);}var artifacts=data.json.createObjectNode().put("plainText",extracted.plainText()).put("contentSha256",extracted.contentHash());artifacts.putObject("parts").putObject("BODY").put("status","AVAILABLE");SqlSupport.insert(data.db,"INSERT INTO reference_revision(reference_work_id,revision_no,title,content_json,source_metadata_json,processing_status,artifacts_json,created_at) VALUES(?,1,?,?,?,'IMPORTING',?,UTC_TIMESTAMP(3))",w,finalTitle,extracted.document().content().toString(),metadata.toString(),artifacts.toString());record(id,rowNo,source,"IMPORTED",Long.toString(w),"");return Long.toString(w);});known.put(hash,work);
            }catch(ApiException e){record(id,rowNo,source,"REJECTED",null,e.getMessage());}

        }}counts(id);
        data.transactions.executeWithoutResult(tx->{data.db.update("UPDATE reference_work w JOIN reference_import_row b ON b.reference_work_id=w.id SET w.enabled=true WHERE b.batch_id=? AND b.status='IMPORTED'",id);data.db.update("UPDATE reference_revision r JOIN reference_import_row b ON b.reference_work_id=r.reference_work_id SET r.processing_status='PREPARED' WHERE b.batch_id=? AND b.status='IMPORTED' AND r.processing_status='IMPORTING'",id);data.db.update("UPDATE reference_import SET status='INDEXING' WHERE id=?",id);});
        references.refresh(true);data.db.update("UPDATE reference_import SET status='COMPLETED',generation_id=?,error_message=NULL WHERE id=?",libraries.currentId(),id);
    }
    private String textHash(String text){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(text.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    private void record(String id,int number,String source,String status,String work,String message){data.db.update("INSERT INTO reference_import_row(batch_id,row_no,source_id,status,reference_work_id,message) VALUES(?,?,?,?,?,?)",id,number,source.length()>255?source.substring(0,255):source,status,work,message);if(number%25==0)counts(id);}
    private void counts(String id){data.db.update("UPDATE reference_import SET processed=(SELECT COUNT(*) FROM reference_import_row WHERE batch_id=?),inserted=(SELECT COUNT(*) FROM reference_import_row WHERE batch_id=? AND status='IMPORTED'),duplicates=(SELECT COUNT(*) FROM reference_import_row WHERE batch_id=? AND status='DUPLICATE'),rejected=(SELECT COUNT(*) FROM reference_import_row WHERE batch_id=? AND status='REJECTED') WHERE id=?",id,id,id,id,id);}
}
